css:
.hero {
  margin: 16px;
  padding: 48px 24px;
  border-radius: 12px;
  background-image: linear-gradient(135deg, #ea580c, #7c3aed);
  color: #ffffff;
  font-family: system-ui, sans-serif;
}

.hero-title {
  margin: 0 0 8px;
  font-size: 2.25rem;
}

.hero-text {
  margin: 0;
  font-size: 1.125rem;
}
